import {clamp} from './config.js';import {$} from './ui.js';
export class Controls {
 constructor({run,state,view,audio,pause,toggleAssist}){
  this.getRun=run;this.getState=state;this.view=view;this.audio=audio;this.pause=pause;this.keys=new Set();this.firePointers=new Set();this.sprintPointers=new Set();this.mouseFire=false;this.mouseAim=false;this.aimToggle=false;this.axis=0;this.forward=0;this.look=null;this.stick=null;
  const active=()=>state()==='play'&&run().phase==='running',canvas=$('world');
  window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;const k=e.key.toLowerCase();if(['escape','p'].includes(k)){e.preventDefault();pause();return;}if(!active())return;if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();this.keys.add(k);if(e.repeat)return;const r=run();if(k==='enter'){r.setAim(this.ray());r.fire();}if(k===' ')r.jump();if(k==='control')r.crouch();if(k==='r')r.reloadGun();if(k==='q')r.switchWeapon();if(k==='z')r.dodge(-1);if(k==='x')r.dodge(1);if(k==='e')r.interact();if(k==='c')r.commandDog();if(k==='f')toggleAssist();if(k==='m')$('explorationMap').hidden=!$('explorationMap').hidden;if(/^[1-6]$/.test(k))r.switchWeapon(['pistol','revolver','shotgun','rifle','smg','hunting'][Number(k)-1]);if(k==='v')this.aimToggle=!this.aimToggle;});
  window.addEventListener('keyup',e=>this.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{this.clear();pause(false);});document.addEventListener('visibilitychange',()=>{if(document.hidden){this.clear();pause(false);}});
  canvas.addEventListener('contextmenu',e=>e.preventDefault());
  canvas.addEventListener('mousedown',e=>{if(!active())return;e.preventDefault();audio.unlock().catch(()=>{});if(e.button===2){this.mouseAim=true;this.mouseLook={x:e.clientX,y:e.clientY};}if(e.button===0){this.mouseFire=true;run().setAim(this.ray());run().fire();if(!document.pointerLockElement){try{canvas.requestPointerLock()?.catch(()=>{});}catch{}}}});
  window.addEventListener('mouseup',e=>{if(e.button===0)this.mouseFire=false;if(e.button===2)this.mouseAim=false;});
  document.addEventListener('mousemove',e=>{if(!active())return;if(document.pointerLockElement===canvas||this.mouseAim){const locked=document.pointerLockElement===canvas,dx=locked?e.movementX:e.clientX-(this.mouseLook?.x??e.clientX),dy=locked?e.movementY:e.clientY-(this.mouseLook?.y??e.clientY);this.mouseLook={x:e.clientX,y:e.clientY};view.rigCamera.look(dx,dy,run().profile.settings.sensitivity);run().viewYaw=view.rigCamera.yaw;view.rigCamera.pointer={x:.5,y:.46};this.reticle();}else if(e.target===canvas)this.pointer(e.clientX,e.clientY);});
  canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||!active())return;this.look={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});
  canvas.addEventListener('pointermove',e=>{if(this.look?.id!==e.pointerId)return;view.rigCamera.look(e.clientX-this.look.x,e.clientY-this.look.y,run().profile.settings.sensitivity*1.6);run().viewYaw=view.rigCamera.yaw;view.rigCamera.pointer={x:.5,y:.46};this.look.x=e.clientX;this.look.y=e.clientY;this.reticle();});
  const pad=$('steerpad');pad.addEventListener('pointerdown',e=>{if(!active())return;e.preventDefault();pad.setPointerCapture(e.pointerId);this.stick={id:e.pointerId};this.steer(e);});pad.addEventListener('pointermove',e=>{if(this.stick?.id===e.pointerId)this.steer(e);});
  const release=e=>{this.firePointers.delete(e.pointerId);this.sprintPointers.delete(e.pointerId);if(this.stick?.id===e.pointerId){this.axis=this.forward=0;this.stick=null;$('steerknob').style.transform='translate(0,0)';pad.setAttribute('aria-valuenow','0');}if(this.look?.id===e.pointerId)this.look=null;};window.addEventListener('pointerup',release);window.addEventListener('pointercancel',release);
  for(const b of document.querySelectorAll('[data-action]'))b.addEventListener('pointerdown',e=>{if(!active())return;e.preventDefault();e.stopPropagation();b.setPointerCapture(e.pointerId);const r=run(),a=b.dataset.action;audio.unlock().catch(()=>{});if(a==='fire'){this.firePointers.add(e.pointerId);r.setAim(this.ray());r.fire();}if(a==='sprint')this.sprintPointers.add(e.pointerId);if(a==='aim'){this.aimToggle=!this.aimToggle;b.setAttribute('aria-pressed',String(this.aimToggle));}if(a==='jump')r.jump();if(a==='slide')r.crouch();if(a==='reload')r.reloadGun();if(a==='swap')r.switchWeapon();if(a==='use')r.interact();if(a==='dog')r.commandDog();if(a==='map')$('explorationMap').hidden=!$('explorationMap').hidden;});
 }
 steer(e){const b=$('steerpad').getBoundingClientRect(),dx=(e.clientX-b.x-b.width/2)/(b.width*.36),dy=-(e.clientY-b.y-b.height/2)/(b.height*.36),n=Math.max(1,Math.hypot(dx,dy));this.axis=dx/n;this.forward=dy/n;$('steerknob').style.transform=`translate(${this.axis*27}px,${-this.forward*27}px)`;$('steerpad').setAttribute('aria-valuenow',String(Math.round(this.axis*100)));}
 pointer(x,y){this.view.rigCamera.pointer={x:clamp(x/innerWidth,.02,.98),y:clamp(y/innerHeight,.05,.95)};this.reticle();}
 reticle(){const {x,y}=this.view.rigCamera.pointer;for(const id of ['reticle','hitmarker']){$(id).style.left=x*100+'%';$(id).style.top=y*100+'%';}}
 ray(){const r=this.getRun(),p=this.view.rigCamera.pointer,ray=this.view.rigCamera.ray(r,p.x,p.y);ray.muzzle=this.view.muzzle(r);return ray;}
 sample(){if(this.keys.has('j'))this.view.rigCamera.look(-9,0);if(this.keys.has('l'))this.view.rigCamera.look(9,0);this.getRun().viewYaw=this.view.rigCamera.yaw;return {axis:clamp(this.axis+(this.keys.has('d')||this.keys.has('arrowright')?1:0)-(this.keys.has('a')||this.keys.has('arrowleft')?1:0),-1,1),forward:clamp(this.forward+(this.keys.has('w')||this.keys.has('arrowup')?1:0)-(this.keys.has('s')||this.keys.has('arrowdown')?1:0),-1,1),fire:this.mouseFire||this.firePointers.size>0||this.keys.has('enter'),sprint:this.keys.has('shift')||this.sprintPointers.size>0,aim:this.mouseAim||this.aimToggle};}
 clear(){this.keys.clear();this.firePointers.clear();this.sprintPointers.clear();this.axis=this.forward=0;this.mouseFire=false;this.mouseAim=false;this.look=null;this.stick=null;$('steerknob').style.transform='translate(0,0)';if(document.pointerLockElement)document.exitPointerLock();}
}
